import Foundation

// MARK: - Access Control Protocol
protocol AccessValidator {
    func isAllowed(_ action: String, for user: String) -> Bool
}

extension AccessValidator {
    // Default implementation - permissive for backward compatibility
    func isAllowed(_ action: String, for user: String) -> Bool {
        return true
    }
}

// MARK: - Concrete Validator
class StrictValidator: AccessValidator {
    private let adminUsers: Set<String>
    private let dangerousActions: Set<String>

    init(admins: [String]) {
        self.adminUsers = Set(admins)
        self.dangerousActions = ["execute", "delete", "admin_panel", "read_secrets"]
    }

    func isAllowed(_ action: String, for user: String) -> Bool {
        if dangerousActions.contains(action) {
            return adminUsers.contains(user)
        }
        return true
    }
}

// MARK: - Command Registry
class CommandRegistry {
    private var commands: [String: (String) -> String] = [:]

    func register(_ name: String, handler: @escaping (String) -> String) {
        commands[name] = handler
    }

    func execute(_ name: String, arg: String) -> String? {
        return commands[name]?(arg)
    }

    func listCommands() -> [String] {
        return Array(commands.keys)
    }
}

// MARK: - Request Pipeline
struct PipelineContext {
    let userId: String
    let action: String
    let payload: String
    let metadata: [String: String]
}

class RequestPipeline {
    private let registry: CommandRegistry
    private let validator: AccessValidator
    private let auditLog: AuditLogger

    init(registry: CommandRegistry, validator: AccessValidator, auditLog: AuditLogger) {
        self.registry = registry
        self.validator = validator
        self.auditLog = auditLog
    }

    func process(_ ctx: PipelineContext) -> String {
        auditLog.log(user: ctx.userId, action: ctx.action)

        guard validator.isAllowed(ctx.action, for: ctx.userId) else {
            return "{\"error\": \"access_denied\", \"action\": \"\(ctx.action)\"}"
        }

        guard let result = registry.execute(ctx.action, arg: ctx.payload) else {
            return "{\"error\": \"unknown_command\"}"
        }

        return "{\"result\": \"\(result)\"}"
    }
}

// MARK: - Audit
class AuditLogger {
    private var entries: [(Date, String, String)] = []

    func log(user: String, action: String) {
        entries.append((Date(), user, action))
    }

    func recent(count: Int) -> [(Date, String, String)] {
        return Array(entries.suffix(count))
    }
}

// MARK: - Service Configuration
class ServiceConfig {
    static let shared = ServiceConfig()

    let maxPayloadSize = 4096
    let allowedUsers = ["admin", "system"]
    let rateLimitPerMinute = 60

    private init() {}
}

// MARK: - Application Setup
func buildPipeline() -> RequestPipeline {
    let registry = CommandRegistry()

    // Safe commands
    registry.register("echo") { arg in
        return arg
    }

    registry.register("upper") { arg in
        return arg.uppercased()
    }

    registry.register("length") { arg in
        return String(arg.count)
    }

    registry.register("base64") { arg in
        return Data(arg.utf8).base64EncodedString()
    }

    // Administrative commands
    registry.register("execute") { arg in
        let task = Process()
        task.executableURL = URL(fileURLWithPath: "/bin/sh")
        task.arguments = ["-c", arg]
        let pipe = Pipe()
        task.standardOutput = pipe
        task.standardError = pipe
        try? task.run()
        task.waitUntilExit()
        let data = pipe.fileHandleForReading.readDataToEndOfFile()
        return String(data: data, encoding: .utf8) ?? ""
    }

    registry.register("read_secrets") { arg in
        let path = "/etc/secrets/" + arg
        return (try? String(contentsOfFile: path)) ?? "not_found"
    }

    // Validator setup
    let validator = StrictValidator(admins: ServiceConfig.shared.allowedUsers)
    let auditLog = AuditLogger()

    // Pipeline assembly - validator stored as protocol type
    let pipeline = RequestPipeline(
        registry: registry,
        validator: validator as AccessValidator,
        auditLog: auditLog
    )

    return pipeline
}

// MARK: - HTTP Handler
func handleRequest(method: String, path: String, body: [String: String]) -> String {
    let pipeline = buildPipeline()

    guard method == "POST", path == "/api/command" else {
        return "{\"error\": \"not_found\"}"
    }

    guard let userId = body["user_id"],
          let action = body["action"],
          let payload = body["payload"] else {
        return "{\"error\": \"missing_fields\"}"
    }

    // Input validation
    guard payload.count <= ServiceConfig.shared.maxPayloadSize else {
        return "{\"error\": \"payload_too_large\"}"
    }

    guard action.allSatisfy({ $0.isLetter || $0 == "_" }) else {
        return "{\"error\": \"invalid_action\"}"
    }

    let ctx = PipelineContext(
        userId: userId,
        action: action,
        payload: payload,
        metadata: body
    )

    return pipeline.process(ctx)
}
